with target as(select * from public.works where id=any(array[]::bigint[]) or open_library_id=any(array['OL7817844W','OL8063393W','OL8067065W','OL9100941W','OL9103413W','OL9103415W','OL9103416W','OL9103417W','OL9103418W','OL9103421W','OL9103422W','OL9709767W','OL9709768W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['debevrijdingaandekust','geloof','onbelief','dienarenvanhetgoddelijkplan','deatlantischemuurdeel2','deatlantischemuur2a','debunkers','bommenwerpersbovenbelgie19421943','delaatstevluchtvanyvonneproudbagbelgieinoorlog','doelwitleiven','doelwitleuven','luchtgevechtenbovenbelgie19411942','luchtslagbovenhetkanaal','rafbommenwerpersbovenbelgie19401942','vavv','derondekamer2eeditie','dreumes']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['debevrijdingaandekust','geloof','onbelief','dienarenvanhetgoddelijkplan','deatlantischemuurdeel2','deatlantischemuur2a','debunkers','bommenwerpersbovenbelgie19421943','delaatstevluchtvanyvonneproudbagbelgieinoorlog','doelwitleiven','doelwitleuven','luchtgevechtenbovenbelgie19411942','luchtslagbovenhetkanaal','rafbommenwerpersbovenbelgie19401942','vavv','derondekamer2eeditie','dreumes']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL2479780A','OL3278524A','OL904271A','OL3200559A','OL3202185A','OL3701061A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['tomastermote','slavojzizek','anonymous','dirkpeeters','alainvangeeteruyen','cynrikdedecker','jeanlouisroba','fransvanderauwera','dawnavalon']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL12846188M','OL10188206M','OL12186469M','OL9107469M','OL9112672M','OL9112673M','OL9112681M','OL12851269M','OL12851267M','OL12851268M','OL12846177M','OL11916485M','OL11689677M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789058680587','9780415282161','9781889280349','9789058680167','9789072547149','9789072547156','9789072547613','9789072547132','9789072547095','9789072547118','9789058680211','9781847282781','9781411611955']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
